import{_ as a,o as t,c as e,a2 as i}from"./chunks/framework.CtrpDQpp.js";const n="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNsaGj4DwAFhAJ/2eTjmwAAAABJRU5ErkJggg==",l="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNsaGj4DwAFhAJ/2eTjmwAAAABJRU5ErkJggg==",o="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNsaGj4DwAFhAJ/2eTjmwAAAABJRU5ErkJggg==",r="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNsaGj4DwAFhAJ/2eTjmwAAAABJRU5ErkJggg==",u=JSON.parse('{"title":"第 12 章 主题安装与管理","description":"","frontmatter":{},"headers":[],"relativePath":"12-theme-management.md","filePath":"12-theme-management.md","lastUpdated":1792595797000}'),d={name:"12-theme-management.md"};function h(p,s,c,g,k,m){return t(),e("div",null,[...s[0]||(s[0]=[i(`<h1 id="第-12-章-主题安装与管理" tabindex="-1">第 12 章 主题安装与管理 <a class="header-anchor" href="#第-12-章-主题安装与管理" aria-label="Permalink to &quot;第 12 章 主题安装与管理&quot;">​</a></h1><p>🟢 <strong>入门难度</strong> ｜ 一句话导览：选好主题只是开始，安全地上车、更新和回滚才是日常运维。本章从三种安装方式讲起，帮你理解主题更新机制、建立备份与子主题保护意识，再讲清楚「预览不启用」「删除兜底」「白屏回滚」等高频实战场景。</p><h2 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to &quot;学习目标&quot;">​</a></h2><ul><li>能独立通过三种方式（后台搜索、ZIP 上传、FTP/SFTP）安装并启用主题</li><li>理解主题更新机制：WordPress 如何发现更新、自动更新开关在哪里、为什么更新前必须确认父子关系</li><li>掌握主题删除的正确顺序：先切换、保留一个默认主题兜底</li><li>能使用「实时预览」功能评估主题而不影响前台</li><li>理解多站点网络中主题的网络启用规则（简介）</li><li>遇到安装失败、白屏、缺少 style.css 报错时，能按故障排查表独立定位原因</li></ul><h2 id="_12-1-三种安装方式" tabindex="-1">12.1 三种安装方式 <a class="header-anchor" href="#_12-1-三种安装方式" aria-label="Permalink to &quot;12.1 三种安装方式&quot;">​</a></h2><p>主题本质就是一组文件，放到 <code>wp-content/themes/</code> 目录下即可被 WordPress 识别。三个安装路径的区别在于「谁负责搬运这组文件」：</p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    A[拿到一个主题] --&gt; B{主题在哪?}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    B --&gt;|官方库有| C[后台在线安装&lt;br/&gt;外观→主题→添加新主题]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    B --&gt;|本地 ZIP 包| D{后台能传文件?}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    D --&gt;|能| E[上传 ZIP 安装&lt;br/&gt;添加新主题→上传主题]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    D --&gt;|不能/后台进不去| F[FTP/SFTP 手动上传&lt;br/&gt;解压后放入 wp-content/themes/]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    B --&gt;|已经在服务器上| F</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C --&gt; G[外观→主题 启用]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    E --&gt; G</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    F --&gt; G</span></span></code></pre></div><p>三条路殊途同归，最后一步都是后台启用。本章 12.1.1–12.1.3 分别展开。</p><h3 id="_12-1-1-后台在线安装-推荐新手" tabindex="-1">12.1.1 后台在线安装（推荐新手） <a class="header-anchor" href="#_12-1-1-后台在线安装-推荐新手" aria-label="Permalink to &quot;12.1.1 后台在线安装（推荐新手）&quot;">​</a></h3><h4 id="原理说明" tabindex="-1">原理说明 <a class="header-anchor" href="#原理说明" aria-label="Permalink to &quot;原理说明&quot;">​</a></h4><p>后台 <strong>外观 → 主题 → 安装主题</strong> 调用 WordPress 内置的 <code>wp_remote_get()</code> 从官方主题库（或你挂的市场）下载压缩包、解压到 <code>wp-content/themes/</code>、校验文件头。全过程由 PHP 脚本完成，对主机环境的要求是：Web 进程用户对 <code>wp-content/</code> 有写权限。</p><h4 id="操作方法-从官方库搜索-筛选-预览-安装-启用" tabindex="-1">操作方法：从官方库搜索/筛选/预览/安装/启用 <a class="header-anchor" href="#操作方法-从官方库搜索-筛选-预览-安装-启用" aria-label="Permalink to &quot;操作方法：从官方库搜索/筛选/预览/安装/启用&quot;">​</a></h4><ol><li>登录后台，依次点击 <strong>外观 → 主题 → 添加新主题</strong>（或顶部「安装主题」按钮）；</li><li>搜索框输入关键词（如 <code>blog</code> <code>education</code> <code>block theme</code>），或点击「特征过滤」按布局/功能筛选（筛选逻辑见<a href="./11-theme-ecosystem#_11-3-2-操作方法-用特征过滤缩小范围">第 11 章 11.3.2 节</a>）；</li><li>鼠标悬停到心仪主题卡片上，出现三个按钮： <ul><li><strong>详情与预览</strong> → 弹出预览窗口，左栏显示该主题提供的演示站点，你可以交互式浏览首页、文章页、分类页，直观感受排版与响应式；</li><li><strong>安装</strong> → 下载并解压到 <code>wp-content/themes/主题名/</code>，<strong>不自动启用</strong>；</li><li><strong>导入演示数据</strong>（部分主题提供）→ 一键导入首页布局、演示文章、菜单结构——<strong>建议本地/测试站先用，正式站务必在备份后导入</strong>；</li></ul></li><li>安装完成后回到主题列表，点击 <strong>「启用」</strong> 使主题生效。</li></ol><p><img src="`+n+'" alt="图 12-1：后台主题安装流程"><em>图 12-1：安装主题四步——搜索 → 预览 → 安装 → 启用，每步按钮位置与预期效果</em></p><blockquote><p>💡 安装后不要急着启用，先点「实时预览」在隔离环境里看看你的实际内容和导航在这个主题下长什么样。预览窗口的地址栏是 <code>?theme=主题目录名</code>，不会写入数据库的「已启用」状态，完全安全。</p></blockquote><h4 id="更新与版本提示" tabindex="-1">更新与版本提示 <a class="header-anchor" href="#更新与版本提示" aria-label="Permalink to &quot;更新与版本提示&quot;">​</a></h4><p>如果已安装主题的右侧出现「有新版本可用」提示，说明 WordPress 后台已检测到官方库的新版本。更新方式见 12.2 节。</p><h3 id="_12-1-2-上传-zip-包安装" tabindex="-1">12.1.2 上传 ZIP 包安装 <a class="header-anchor" href="#_12-1-2-上传-zip-包安装" aria-label="Permalink to &quot;12.1.2 上传 ZIP 包安装&quot;">​</a></h3><h4 id="原理说明-1" tabindex="-1">原理说明 <a class="header-anchor" href="#原理说明-1" aria-label="Permalink to &quot;原理说明&quot;">​</a></h4><p>当主题不在官方库（如商业主题、自建主题、朋友发来的定制包），WordPress 提供<strong>上传 ZIP</strong> 通道。上传后 PHP 把 zip 解压到 <code>wp-content/themes/</code> 目录，再读取 <code>style.css</code> 头注释确认主题合法性。</p><h4 id="操作方法" tabindex="-1">操作方法 <a class="header-anchor" href="#操作方法" aria-label="Permalink to &quot;操作方法&quot;">​</a></h4><ol><li>拿到主题 ZIP 包（从商业商店下载、或本地开发打包），确认包里<strong>不要再套一层目录</strong>——常见错误是压缩时把主题文件夹本身也压进去，导致解压后变成 <code>wp-content/themes/外层文件夹/主题实际文件夹/…</code>，WordPress 找不到 <code>style.css</code> 就会报「缺少 style.css」（12.6.1 节详讲）；</li><li>后台 <strong>外观 → 主题 → 添加新主题 → 上传主题</strong>；</li><li>点击「选择文件」，选中 ZIP，点「立即安装」；</li><li>安装成功提示「主题安装成功」后，可选择「启用」或「实时预览」。</li></ol><p><img src="'+l+`" alt="图 12-2：上传 ZIP 安装主题"><em>图 12-2：上传主题入口在「添加新主题」页顶部，红色区域为文件选择控件与立即安装按钮</em></p><h4 id="压缩包嵌套排查清单" tabindex="-1">压缩包嵌套排查清单 <a class="header-anchor" href="#压缩包嵌套排查清单" aria-label="Permalink to &quot;压缩包嵌套排查清单&quot;">​</a></h4><p>上传后报「缺少 style.css」？先不急着找主题作者，大概率是压缩包结构问题。正确结构 vs 错误结构：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>正确（可直接安装）:</span></span>
<span class="line"><span>  wp-academy.zip</span></span>
<span class="line"><span>  ├── style.css      ← zip 解压后第一层就是主题文件</span></span>
<span class="line"><span>  ├── index.php</span></span>
<span class="line"><span>  └── …</span></span>
<span class="line"><span></span></span>
<span class="line"><span>错误（嵌套目录）:</span></span>
<span class="line"><span>  wp-academy.zip</span></span>
<span class="line"><span>  └── wp-academy/    ← 多了一层文件夹！</span></span>
<span class="line"><span>      ├── style.css</span></span>
<span class="line"><span>      ├── index.php</span></span>
<span class="line"><span>      └── …</span></span></code></pre></div><p>修正方法：在本地解压 ZIP，把里面的实际主题文件夹单独重新压缩（选文件夹本身而非外层包裹），再上传。</p><h3 id="_12-1-3-ftp-sftp-手动上传" tabindex="-1">12.1.3 FTP/SFTP 手动上传 <a class="header-anchor" href="#_12-1-3-ftp-sftp-手动上传" aria-label="Permalink to &quot;12.1.3 FTP/SFTP 手动上传&quot;">​</a></h3><h4 id="原理说明-2" tabindex="-1">原理说明 <a class="header-anchor" href="#原理说明-2" aria-label="Permalink to &quot;原理说明&quot;">​</a></h4><p>后台安装依赖 PHP 的写权限和 zip 扩展，某些安全加固过的主机（或你暂时进不了后台时）只能走 FTP/SFTP 手工搬运文件。SFTP 基于 SSH，传输加密，生产环境优先使用。</p><h4 id="操作方法-1" tabindex="-1">操作方法 <a class="header-anchor" href="#操作方法-1" aria-label="Permalink to &quot;操作方法&quot;">​</a></h4><ol><li>用 FileZilla、Transmit、或命令行 <code>sftp</code> 连接服务器；</li><li>定位到远程目录 <code>wp-content/themes/</code>；</li><li>把主题文件夹（注意是解压后的文件夹，不是 ZIP）直接拖进 <code>themes/</code>；</li><li>确认目录权限为 <code>755</code>（若属主是 PHP 运行用户，755 即可写入；否则可能需要 <code>775</code>，具体见<a href="./03-server-environment#_3-11-常见问题速查">第 03 章 3.11 节</a>）；</li><li>回到后台 <strong>外观 → 主题</strong>，新主题已出现在列表里，点击「启用」。</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 命令行等价操作（服务器上执行）</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/www/wordpress/wp-content/themes/</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 上传主题目录（本地 → 远程）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">scp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /本地路径/wp-academy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user@服务器:/var/www/wordpress/wp-content/themes/</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 确认权限</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chown</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -R</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> www-data:www-data</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wp-academy</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -R</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 755</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wp-academy</span></span></code></pre></div><h4 id="什么时候必须走-ftp-sftp" tabindex="-1">什么时候必须走 FTP/SFTP <a class="header-anchor" href="#什么时候必须走-ftp-sftp" aria-label="Permalink to &quot;什么时候必须走 FTP/SFTP&quot;">​</a></h4><table tabindex="0"><thead><tr><th>场景</th><th>原因</th></tr></thead><tbody><tr><td>主机商禁用了 PHP 文件上传（<code>file_uploads = Off</code>）</td><td>后台上传 ZIP 不可用</td></tr><tr><td>安全加固：<code>wp-content</code> 不可写</td><td>后台在线安装会弹 FTP 凭据框（见<a href="./04-installation#_4-10-3-在线安装时弹出-ftp-凭据框">第 04 章 4.10.3 节</a>）</td></tr><tr><td>后台白屏 / 无法登录</td><td>无法通过后台安装，只能用 FTP 换主题回滚（12.6.3 节）</td></tr><tr><td>一次性批量部署多个主题</td><td>命令行打包压缩后 SFTP 上传解压，比逐个后台点更快</td></tr></tbody></table><h2 id="_12-2-主题更新机制" tabindex="-1">12.2 主题更新机制 <a class="header-anchor" href="#_12-2-主题更新机制" aria-label="Permalink to &quot;12.2 主题更新机制&quot;">​</a></h2><h3 id="_12-2-1-原理说明" tabindex="-1">12.2.1 原理说明 <a class="header-anchor" href="#_12-2-1-原理说明" aria-label="Permalink to &quot;12.2.1 原理说明&quot;">​</a></h3><p>WordPress 每 12 小时通过 wp-cron 向官方更新服务器（<code>api.wordpress.org</code>）发送一次检查请求。请求中携带已安装主题的目录名、版本号、本地化信息，服务器返回是否有新版。若有，后台仪表盘和 <strong>外观 → 主题</strong> 列表都会显示「更新可用」提示。</p><p>商业主题不走官方更新通道，它们通常通过自定义更新端点（内嵌在主题里的 <code>update.php</code>）或配套插件推送更新。更新来源不同，但操作入口相同——都在后台的更新提示里一键完成。</p><p>值得知道的三个底层细节：</p><ol><li><strong>更新检查是异步的</strong>：wp-cron 定时任务触发，不是每次进后台都实时查。所以主题作者刚发布新版，你的后台可能要几小时后才出现提示；想立刻检查，可点 <strong>仪表盘 → 更新 → 再次检查</strong> 强制刷新；</li><li><strong>版本号是唯一比较依据</strong>：更新服务器只比对版本号字符串，不比对文件内容。如果你手工改过主题文件但没改版本号，官方更新来了照样会整个覆盖——这是 12.2.3 检查清单反复强调「别改父主题」的技术原因；</li><li><strong>更新过程有维护模式</strong>：更新期间 WordPress 会创建 <code>.maintenance</code> 文件，访客看到「正在执行例行维护」提示。正常几秒完成；若更新中断导致 <code>.maintenance</code> 残留，手动到站点根目录删除该文件即可恢复。</li></ol><h3 id="_12-2-2-操作方法-手动更新与自动更新" tabindex="-1">12.2.2 操作方法：手动更新与自动更新 <a class="header-anchor" href="#_12-2-2-操作方法-手动更新与自动更新" aria-label="Permalink to &quot;12.2.2 操作方法：手动更新与自动更新&quot;">​</a></h3><h4 id="手动更新" tabindex="-1">手动更新 <a class="header-anchor" href="#手动更新" aria-label="Permalink to &quot;手动更新&quot;">​</a></h4><ol><li>后台 <strong>仪表盘 → 更新</strong>（或 <strong>外观 → 主题</strong>），找到提示「有新版本可用」的主题；</li><li>点击「立即更新」——WordPress 自动下载新版、覆盖旧版文件、保留你通过自定义器或站点编辑器做的配置（这些配置存在数据库里，不在主题文件中）；</li><li>更新完成后刷新前台，确认无异常。</li></ol><blockquote><p>⚠️ 如果当前主题有<strong>子主题</strong>（见<a href="./15-child-themes">第 15 章</a>），更新<strong>父主题</strong>是安全的——子主题的文件不会被覆盖，只有父主题目录里的文件被替换。但如果你直接修改过父主题文件（而没有用子主题），更新会把你的修改全部擦除。这也是为什么第 15 章反复强调「定制走子主题」。</p></blockquote><h4 id="自动更新开关" tabindex="-1">自动更新开关 <a class="header-anchor" href="#自动更新开关" aria-label="Permalink to &quot;自动更新开关&quot;">​</a></h4><p>WordPress 7.x 默认对新安装的官方库主题<strong>不开启</strong>自动更新（早期版本行为有变化，请以你的后台为准）。开关位置：</p><ol><li><strong>外观 → 主题</strong> → 点击任一已安装主题 → 主题详情弹窗右下角出现「启用自动更新」按钮；</li><li>或者在 <strong>仪表盘 → 更新</strong> 页面，勾选「所有主题」下方的自动更新选项。</li></ol><p>自动更新的利弊：</p><table tabindex="0"><thead><tr><th>立场</th><th>利</th><th>弊</th></tr></thead><tbody><tr><td>站长/管理员</td><td>安全补丁自动落盘，减少人工维护量</td><td>主题大版本更新可能引入视觉变化或兼容性问题，前台「一夜之间变样」</td></tr><tr><td>开发者</td><td>鼓励用户始终使用最新版，降低旧版兼容负担</td><td>用户自动升级后遇到问题，你未必知道他们刚更新了</td></tr></tbody></table><p>建议：</p><ul><li><strong>生产站</strong>：手动更新，且更新前先本地测试；</li><li><strong>个人博客/练手站</strong>：可开自动更新，出问题损失可控；</li><li><strong>使用了子主题的站点</strong>：父主题自动更新不影响定制，风险更低。</li></ul><p><img src="`+o+'" alt="图 12-3：主题详情页的自动更新开关"><em>图 12-3：主题详情弹窗右下角，「启用自动更新」按钮与当前版本号并列显示</em></p><h3 id="_12-2-3-更新前检查清单" tabindex="-1">12.2.3 更新前检查清单 <a class="header-anchor" href="#_12-2-3-更新前检查清单" aria-label="Permalink to &quot;12.2.3 更新前检查清单&quot;">​</a></h3><p>每次点「更新」前，花 30 秒过一遍：</p><ol><li><strong>是否使用了子主题？</strong> 若无，确认自己没有直接改过父主题文件；</li><li><strong>是否有直接修改过主题文件？</strong> 若有，先把这些改动迁移到子主题或记录下来；</li><li><strong>本地/测试站先跑一遍</strong>：主题大版本更新（如 2.x → 3.x）尤其要测试；</li><li><strong>确认 PHP 版本兼容</strong>：新版主题可能提升最低 PHP 要求（如从 8.0 提到 8.3），更新前核对主机环境；</li><li><strong>备份</strong>：至少做一次数据库快照（<a href="./34-backup">第 05 章</a>讲备份插件），主题文件本身可通过 FTP 下载备份。</li></ol><h2 id="_12-3-预览不启用-live-preview" tabindex="-1">12.3 预览不启用：Live Preview <a class="header-anchor" href="#_12-3-预览不启用-live-preview" aria-label="Permalink to &quot;12.3 预览不启用：Live Preview&quot;">​</a></h2><h3 id="_12-3-1-原理说明" tabindex="-1">12.3.1 原理说明 <a class="header-anchor" href="#_12-3-1-原理说明" aria-label="Permalink to &quot;12.3.1 原理说明&quot;">​</a></h3><p>「实时预览」是 WordPress 在切换主题前给你搭的一个<strong>隔离沙箱</strong>。它在当前 URL 上附加 <code>?theme=目标主题目录名</code> 参数，用目标主题的模板渲染页面，但<strong>不写入数据库的已启用主题字段</strong>。预览期间，访客看到的前台依然是旧主题，只有你自己能看到新主题效果。</p><h3 id="_12-3-2-操作方法" tabindex="-1">12.3.2 操作方法 <a class="header-anchor" href="#_12-3-2-操作方法" aria-label="Permalink to &quot;12.3.2 操作方法&quot;">​</a></h3><ol><li><strong>外观 → 主题</strong> → 鼠标悬停到未启用的主题 → 点击 <strong>「实时预览」</strong>；</li><li>预览窗口分为左右/上下两栏（取决于屏幕尺寸）：一侧是你的站点内容，一侧是自定义器选项面板；</li><li>在自定义器里调整 logo、颜色、菜单位置，这些改动<strong>在点「保存并发布」前不会生效</strong>；</li><li>若满意，点击顶部 <strong>「激活并发布」</strong>（或直接退出预览后点「启用」）；若不满意，关闭预览窗口即可，一切恢复原样。</li></ol><blockquote><p>💡 预览窗口的自定义器只能调整<strong>目标主题暴露的选项</strong>。如果目标主题没有在自定义器里注册某个设置（比如它不提供「页脚文字」选项），你在预览里也改不了——这不是 bug，是主题的功能边界。第 13 章会详细讲自定义器与站点编辑器的选项差异。</p></blockquote><h3 id="_12-3-3-预览的局限" tabindex="-1">12.3.3 预览的局限 <a class="header-anchor" href="#_12-3-3-预览的局限" aria-label="Permalink to &quot;12.3.3 预览的局限&quot;">​</a></h3><ul><li><strong>插件兼容性</strong>：预览环境下部分插件可能未加载（尤其依赖 <code>template_redirect</code> 或前台钩子的插件），导致「预览时购物车按钮不见，启用后又出现」——这不是主题问题，是预览沙箱的限制；</li><li><strong>缓存干扰</strong>：若站点启用了页面缓存插件（如 WP Rocket、W3 Total Cache），预览 URL 可能被缓存为旧主题内容，建议预览时临时排除 <code>?theme=</code> 参数，或清空缓存再试；</li><li><strong>区块主题无自定义器预览</strong>：区块主题在 7.x 中通常不提供自定义器入口，预览直接跳转站点编辑器。这是两代主题的体系差异，第 13 章会展开。</li></ul><h4 id="一个推荐的预览评估流程" tabindex="-1">一个推荐的预览评估流程 <a class="header-anchor" href="#一个推荐的预览评估流程" aria-label="Permalink to &quot;一个推荐的预览评估流程&quot;">​</a></h4><p>面对一个候选主题，按这个顺序在预览里过一遍（全程约 5 分钟）：</p><ol><li><strong>首页</strong>：布局是否符合预期？特色图尺寸是否合理？</li><li><strong>一篇长文章</strong>：正文字号、行高、段落间距是否适合中文阅读？标题层级是否清晰？</li><li><strong>归档页</strong>（点一个分类）：文章列表样式、摘要长度、分页控件；</li><li><strong>移动端</strong>：预览窗口通常有设备切换按钮，切到手机视图看导航折叠与内容溢出；</li><li><strong>404 页</strong>：地址栏随便输个不存在的路径，看主题的 404 模板是否友好（这个细节最能暴露主题的打磨程度）；</li><li><strong>自定义器选项</strong>：翻一遍左侧面板，确认主题提供的可调节项是否覆盖你的需求（logo、颜色、页脚、布局开关）。</li></ol><h2 id="_12-4-多站点网络中的主题启用-简介" tabindex="-1">12.4 多站点网络中的主题启用（简介） <a class="header-anchor" href="#_12-4-多站点网络中的主题启用-简介" aria-label="Permalink to &quot;12.4 多站点网络中的主题启用（简介）&quot;">​</a></h2><h3 id="_12-4-1-原理说明" tabindex="-1">12.4.1 原理说明 <a class="header-anchor" href="#_12-4-1-原理说明" aria-label="Permalink to &quot;12.4.1 原理说明&quot;">​</a></h3><p>WordPress 多站点（Multisite）允许一个安装体运行多个子站（子目录或子域名形式）。在这种架构下，主题的安装和启用分两层：</p><ul><li><strong>网络管理员（Super Admin）</strong>：负责把主题上传到网络级主题目录（和普通单站一样放在 <code>wp-content/themes/</code>），并在 <strong>网络管理 → 主题</strong> 中决定「允许哪些主题供子站使用」；</li><li><strong>子站管理员</strong>：只能在自己站点的 <strong>外观 → 主题</strong> 列表中启用网络已允许的主题，不能安装新主题。</li></ul><h3 id="_12-4-2-操作方法" tabindex="-1">12.4.2 操作方法 <a class="header-anchor" href="#_12-4-2-操作方法" aria-label="Permalink to &quot;12.4.2 操作方法&quot;">​</a></h3><ol><li>以超级管理员身份登录，进入 <strong>我的站点 → 网络管理 → 主题</strong>；</li><li>找到已安装的主题，点击 <strong>「网络启用」</strong>——该主题出现在所有子站的可选列表中；</li><li>若只想让某个主题被特定子站使用，不要点「网络启用」，而是让子站管理员在自己的后台启用（前提是网络管理里没有对该主题做限制）；</li><li>若要让子站完全不能自行切换主题，在 <code>wp-config.php</code> 中定义：</li></ol><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">define</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">( </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;DISALLOW_FILE_MODS&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> );</span></span></code></pre></div><blockquote><p>💡 多站点不是本教程的主线，这里只做概念铺垫。如果你确实要搭建多站点，请阅读 WordPress 官方 Codex「Create a Network」文档，并在测试环境里完整演练一次。</p></blockquote><h4 id="多站点下的三个常见困惑" tabindex="-1">多站点下的三个常见困惑 <a class="header-anchor" href="#多站点下的三个常见困惑" aria-label="Permalink to &quot;多站点下的三个常见困惑&quot;">​</a></h4><ul><li><strong>「子站管理员看不到某主题」</strong>：网络管理员没有对它点「网络启用」，主题不会出现在子站列表里；</li><li><strong>「网络启用 = 强制使用」？</strong> 不是。网络启用只是「允许使用」，子站默认主题仍需管理员到各子站手动启用；真正强制全网络用同一主题需要在 <code>wp-config.php</code> 定义 <code>WP_DEFAULT_THEME</code> 常量；</li><li><strong>更新一次全网生效</strong>：多站点网络里主题只有一份文件，更新后所有启用它的子站同时生效——所以大版本更新前，务必挑一个测试子站先验证。</li></ul><h2 id="_12-5-删除主题-顺序与兜底" tabindex="-1">12.5 删除主题：顺序与兜底 <a class="header-anchor" href="#_12-5-删除主题-顺序与兜底" aria-label="Permalink to &quot;12.5 删除主题：顺序与兜底&quot;">​</a></h2><h3 id="_12-5-1-原理说明" tabindex="-1">12.5.1 原理说明 <a class="header-anchor" href="#_12-5-1-原理说明" aria-label="Permalink to &quot;12.5.1 原理说明&quot;">​</a></h3><p>删除主题 = 删除 <code>wp-content/themes/</code> 下的对应目录。WordPress 禁止删除<strong>当前已启用的主题</strong>（否则前台直接白屏），所以删除流程永远是：<strong>先切到另一个主题，再删除目标主题</strong>。</p><p>为什么必须保留一个默认主题（如 Twenty Twenty-Five）？三个原因：</p><ol><li><strong>排障回退</strong>：当前主题出问题（文件损坏、PHP 致命错误）时，可以迅速切到默认主题验证「是不是主题的问题」；</li><li><strong>自动回退机制</strong>：WordPress 检测到当前主题目录缺失或核心文件损坏时，会尝试自动启用默认主题，避免全站白屏；</li><li><strong>升级保险</strong>：某些 WordPress 核心大版本升级时，会要求至少有一款兼容的默认主题存在，以完成升级后的回退测试。</li></ol><h3 id="_12-5-2-操作方法" tabindex="-1">12.5.2 操作方法 <a class="header-anchor" href="#_12-5-2-操作方法" aria-label="Permalink to &quot;12.5.2 操作方法&quot;">​</a></h3><ol><li>确认当前要删的主题<strong>没有被启用</strong>。如果是当前主题，先启用另一个（建议先启用 Twenty 系列）；</li><li>后台 <strong>外观 → 主题</strong> → 点击要删除的主题 → 主题详情弹窗左下角出现 <strong>「删除」</strong> 链接；</li><li>确认弹窗提示「你确定要删除此主题吗？」→ 点击 <strong>「确定」</strong>；</li><li>WordPress 删除该主题目录，并清理相关自定义器/站点编辑器的用户配置（数据库里的配置不会删，只是不再与该主题关联）。</li></ol><p><img src="'+r+`" alt="图 12-4：主题删除确认弹窗"><em>图 12-4：主题详情弹窗左下角「删除」链接，点击后弹出二次确认</em></p><h4 id="手动删除-ftp-命令行" tabindex="-1">手动删除（FTP/命令行） <a class="header-anchor" href="#手动删除-ftp-命令行" aria-label="Permalink to &quot;手动删除（FTP/命令行）&quot;">​</a></h4><p>如果后台进不去（比如主题损坏导致白屏），只能走文件系统：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># SSH 连接到服务器</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/www/wordpress/wp-content/themes/</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 删除目标主题目录（以要删的损坏主题为例）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> broken-theme</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 确保至少保留一个默认主题</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> twentytwentyfive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> twentytwentyfive-backup</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # 可选备份</span></span></code></pre></div><p>删除后，如果之前启用的就是 <code>broken-theme</code>，WordPress 会自动回退到默认主题；如果没有自动回退，手动改数据库 <code>wp_options</code> 表的 <code>stylesheet</code> 和 <code>template</code> 字段为默认主题目录名（见 12.6.3 节）。</p><h3 id="_12-5-3-子主题删除的特别注意" tabindex="-1">12.5.3 子主题删除的特别注意 <a class="header-anchor" href="#_12-5-3-子主题删除的特别注意" aria-label="Permalink to &quot;12.5.3 子主题删除的特别注意&quot;">​</a></h3><p>删除子主题前，必须确认<strong>父主题没有被依赖</strong>：</p><ul><li>若只删子主题、父主题还在 → 安全，子站只是回到父主题样式；</li><li>若同时删父主题，而某子站启用了基于该父主题的子主题 → 子主题找不到父主题（Template 头指定的目录不存在），前台会报「损坏的主题」甚至白屏。</li></ul><p>所以删除顺序是：<strong>先确保没有子主题依赖该父主题 → 删除子主题 → 最后删除父主题</strong>。</p><p>多站点网络中还有一个额外限制：只要网络里<strong>任何一个子站</strong>正在使用某主题，网络管理员就无法删除它——WordPress 会提示「该主题正被站点使用」。需要先让所有使用它的子站切换到别的主题，才能删除。</p><h4 id="删除前最后确认三件事" tabindex="-1">删除前最后确认三件事 <a class="header-anchor" href="#删除前最后确认三件事" aria-label="Permalink to &quot;删除前最后确认三件事&quot;">​</a></h4><ol><li>该主题不是任何站点的当前启用主题（多站点时检查全网）；</li><li>没有子主题在 <code>Template</code> 头里引用它；</li><li>主题目录里没有你忘记迁移的自定义文件（比如直接改过的模板、传进去的字体文件）——删除不可逆，删前先翻一遍目录。</li></ol><h2 id="_12-6-常见问题" tabindex="-1">12.6 常见问题 <a class="header-anchor" href="#_12-6-常见问题" aria-label="Permalink to &quot;12.6 常见问题&quot;">​</a></h2><h3 id="_12-6-1-上传-zip-报「缺少-style-css」" tabindex="-1">12.6.1 上传 ZIP 报「缺少 style.css」 <a class="header-anchor" href="#_12-6-1-上传-zip-报「缺少-style-css」" aria-label="Permalink to &quot;12.6.1 上传 ZIP 报「缺少 style.css」&quot;">​</a></h3><p>这是新手最高频的安装报错，原因和排查路径：</p><table tabindex="0"><thead><tr><th>原因</th><th>排查方法</th><th>解决</th></tr></thead><tbody><tr><td>ZIP 包嵌套目录（最常见）</td><td>本地解压 ZIP，看是否多一层文件夹</td><td>把实际主题文件夹单独重新压缩</td></tr><tr><td>压缩包里只有截图/文档，没有主题文件</td><td>检查解压后是否有 <code>style.css</code></td><td>找主题作者要正确包</td></tr><tr><td><code>style.css</code> 存在但文件头注释格式错误</td><td>打开 <code>style.css</code> 看开头是否有 <code>/* Theme Name: ... */</code></td><td>补全 Theme Header 字段</td></tr><tr><td>主题是为页面构建器打包的「安装包」</td><td>包里是 <code>.json</code> 或 <code>.xml</code> 而非主题文件</td><td>按构建器文档导入，而非上传主题</td></tr></tbody></table><blockquote><p>💡 如果你从 ThemeForest 下载的包解压后看到一个 <code>Installable WordPress file only.zip</code> 和一个 <code>Documentation</code> 文件夹——真正要上传的是前者，后者只是文档。</p></blockquote><h3 id="_12-6-2-主题损坏-template-头注释错误" tabindex="-1">12.6.2 主题损坏：Template 头注释错误 <a class="header-anchor" href="#_12-6-2-主题损坏-template-头注释错误" aria-label="Permalink to &quot;12.6.2 主题损坏：Template 头注释错误&quot;">​</a></h3><p>经典主题（以及子主题）的 <code>style.css</code> 开头必须有一组<strong>文件头注释（File Header）</strong>，WordPress 靠它识别主题。关键字段：</p><div class="language-css vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">/*</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">Theme Name: WP Academy Child</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">Template: wp-academy          ← 子主题专属：父主题目录名，大小写敏感</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">Version: 1.0.0</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">Text Domain: wp-academy-child</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">*/</span></span></code></pre></div><p>常见错误：</p><ul><li><code>Template: wp-academy</code> 拼错成 <code>wp_academy</code>、<code>wp-Academy</code> 或带了多余空格 → WordPress 找不到父主题，报「损坏的主题」；</li><li>子主题的 <code>Template</code> 行指向的父主题目录不存在 → 同上；</li><li><code>style.css</code> 文件头被保存成 UTF-8 BOM（字节顺序标记）→ WordPress 解析头注释时多出一个不可见字符，导致字段读取失败。解决：用编辑器另存为「UTF-8 无 BOM」。</li></ul><p>排查入口：<strong>外观 → 主题</strong> 页面底部会列出所有「损坏的主题」及具体原因（缺少父主题 / 缺少 style.css / 缺少 index.php），这是定位问题的第一手信息。修好文件头或补齐父主题后，刷新该页面，损坏提示消失、主题回到正常列表。</p><p>区块主题同样有「损坏」概念，但判定条件不同：<code>templates/index.html</code> 缺失或 <code>theme.json</code> 是非法 JSON 都会导致区块主题不可用。遇到非法 JSON 时，把文件贴到任意 JSON 校验工具（或 <code>php -r &#39;var_dump(json_decode(file_get_contents(&quot;theme.json&quot;)));&#39;</code>）即可定位语法错误行。</p><h3 id="_12-6-3-启用白屏-如何用-ftp-改名目录回滚" tabindex="-1">12.6.3 启用白屏：如何用 FTP 改名目录回滚 <a class="header-anchor" href="#_12-6-3-启用白屏-如何用-ftp-改名目录回滚" aria-label="Permalink to &quot;12.6.3 启用白屏：如何用 FTP 改名目录回滚&quot;">​</a></h3><p>场景：启用某个主题后，前台和后台都白屏（空白页），甚至报错 <code>Fatal error: ...</code>。</p><h4 id="为什么改名目录能回滚" tabindex="-1">为什么改名目录能回滚 <a class="header-anchor" href="#为什么改名目录能回滚" aria-label="Permalink to &quot;为什么改名目录能回滚&quot;">​</a></h4><p>WordPress 通过数据库 <code>wp_options</code> 表的 <code>stylesheet</code> 和 <code>template</code> 字段知道当前启用哪个主题。如果它找不到这个目录（因为你改名了），会尝试自动启用默认主题；若默认主题存在，站点立刻恢复可访问。</p><h4 id="回滚操作-ftp-sftp" tabindex="-1">回滚操作（FTP/SFTP） <a class="header-anchor" href="#回滚操作-ftp-sftp" aria-label="Permalink to &quot;回滚操作（FTP/SFTP）&quot;">​</a></h4><ol><li>用 FTP 客户端或命令行连接服务器；</li><li>进入 <code>wp-content/themes/</code>；</li><li>找到当前启用的主题目录（比如 <code>broken-theme</code>），<strong>重命名</strong>为 <code>broken-theme-bak</code>（不要删，留着排障）；</li><li>刷新前台，WordPress 自动回退到默认主题（如 Twenty Twenty-Five）；</li><li>如果能进后台了，去 <strong>外观 → 主题</strong> 确认当前启用的是默认主题，再决定是修复 <code>broken-theme</code> 还是换主题。</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 命令行等价操作</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/www/wordpress/wp-content/themes/broken-theme</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">   /var/www/wordpress/wp-content/themes/broken-theme-bak</span></span></code></pre></div><h4 id="如果默认主题也被删了" tabindex="-1">如果默认主题也被删了 <a class="header-anchor" href="#如果默认主题也被删了" aria-label="Permalink to &quot;如果默认主题也被删了&quot;">​</a></h4><p>若服务器上只剩一个损坏的主题且没有默认主题，WordPress 无法自动回退，会报错。此时只能手动改数据库：</p><ol><li>通过 phpMyAdmin 或命令行连上数据库；</li><li>执行 SQL（把 <code>twentytwentyfive</code> 换成你服务器上实际存在的默认主题目录名）：</li></ol><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">UPDATE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> wp_options </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> option_value </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;twentytwentyfive&#39;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> option_name </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">IN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;template&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;stylesheet&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><ol start="3"><li>刷新前台，站点恢复。</li></ol><blockquote><p>⚠️ 如果表前缀不是 <code>wp_</code>，换成你自己的前缀（如 <code>wpx9_options</code>）。修改数据库前务必先导出备份。</p></blockquote><h3 id="_12-6-4-php-版本不符" tabindex="-1">12.6.4 PHP 版本不符 <a class="header-anchor" href="#_12-6-4-php-版本不符" aria-label="Permalink to &quot;12.6.4 PHP 版本不符&quot;">​</a></h3><p>主题详情页或更新日志中写着 <code>Requires PHP: 8.3</code>，而你的主机还在跑 PHP 8.0，启用该主题可能出现以下症状之一：</p><ul><li>前台白屏，错误日志显示 <code>Parse error: syntax error, unexpected &#39;)&#39;</code>（新版 PHP 语法在旧版上不支持）；</li><li>后台主题列表显示「该主题需要 PHP 8.3，你的服务器运行的是 PHP 8.0」；</li><li>启用后某些页面功能异常（如区块主题在旧 PHP 上渲染失败）。</li></ul><p>解决：按<a href="./03-server-environment#_3-4-php-版本管理">第 03 章 3.4 节</a>升级主机 PHP 版本到 8.3，或在选主题时确认兼容声明。</p><h3 id="_12-6-5-更新后菜单-小工具-自定义设置丢失" tabindex="-1">12.6.5 更新后菜单/小工具/自定义设置丢失 <a class="header-anchor" href="#_12-6-5-更新后菜单-小工具-自定义设置丢失" aria-label="Permalink to &quot;12.6.5 更新后菜单/小工具/自定义设置丢失&quot;">​</a></h3><p><strong>这不是真的「丢失」</strong>，而是新主题注册了不同的菜单位置和小工具区域，旧配置「对不上号」了。</p><p>恢复方法：</p><ol><li><strong>菜单</strong>：进入 <strong>外观 → 菜单</strong>，确认菜单内容还在（菜单位于数据库，不会丢），重新把它分配到新主题的「主导航」「页脚菜单」等位置；</li><li><strong>小工具</strong>：经典主题换经典主题时，旧小工具可能落在「未使用的小工具」区域，拖回新主题的边栏即可；区块主题没有小工具概念，需要手动在站点编辑器里重建；</li><li><strong>自定义器设置</strong>：颜色、logo 等自定义器选项是按主题保存的，换主题后需要在新主题的自定义器里重新设置；</li><li><strong>站点编辑器设置（区块主题）</strong>：样式、模板改动保存在数据库的 <code>wp_posts</code>（模板类型为 <code>wp_template</code>/<code>wp_template_part</code>）和用户配置里，换主题后这些自定义内容理论上保留，但新主题的 <code>theme.json</code> 和模板结构不同，视觉效果会大变。</li></ol><blockquote><p>💡 预防方法：换主题前把旧主题的自定义器设置截图留存，换主题后对着截图逐项复现。</p></blockquote><p>更稳妥的做法是<strong>迁移前全站备份</strong>：数据库（配置、菜单、小工具分配记录都在库里）+ <code>wp-content</code> 目录（主题、插件、上传文件）。这样即使新主题效果不理想，也能整体回滚到迁移前的状态。备份工具与流程在<a href="./34-backup">第 05 章</a>有完整讲解。</p><h2 id="本章总结" tabindex="-1">本章总结 <a class="header-anchor" href="#本章总结" aria-label="Permalink to &quot;本章总结&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>关键动作</th><th>安全/易错点</th></tr></thead><tbody><tr><td>后台在线安装</td><td>搜索 → 预览 → 安装 → 启用</td><td>预览不写入数据库，可大胆试</td></tr><tr><td>ZIP 上传</td><td>确认压缩包不嵌套目录；选文件 → 安装</td><td>嵌套目录 = 最常见的「缺少 style.css」</td></tr><tr><td>FTP/SFTP 上传</td><td>拖文件夹到 <code>wp-content/themes/</code>；后台启用</td><td>确认目录权限 755；确认属主正确</td></tr><tr><td>主题更新</td><td>手动更新优先；更新前确认没有直接改父主题文件</td><td>有子主题则父主题更新安全；大版本先在测试站跑</td></tr><tr><td>自动更新</td><td>外观 → 主题详情里开关</td><td>生产站建议手动；个人站可开</td></tr><tr><td>预览不启用</td><td>实时预览 → 满意再激活</td><td>预览沙箱可能不加载全部插件；缓存会干扰</td></tr><tr><td>删除主题</td><td>先切换 → 再删除；保留一个默认主题兜底</td><td>禁止删当前启用主题；删父主题前先确认无子主题依赖</td></tr><tr><td>白屏回滚</td><td>FTP 改名主题目录 → 自动回退默认主题</td><td>无默认主题时需手动改数据库 <code>template</code>/<code>stylesheet</code></td></tr><tr><td>PHP 不符</td><td>升级主机 PHP 或换兼容主题</td><td>报错可能是语法不兼容，不是主题 bug</td></tr><tr><td>配置「丢失」</td><td>菜单重分配、小工具拖回、自定义器重设</td><td>内容在数据库，只是位置对不上新主题</td></tr></tbody></table><h2 id="动手练习" tabindex="-1">动手练习 <a class="header-anchor" href="#动手练习" aria-label="Permalink to &quot;动手练习&quot;">​</a></h2><p><strong>练-12-01（操作题）｜三种安装方式各走一遍</strong></p><p>在本地练习站上：① 从官方库搜索并安装一个区块主题（如 Twenty Twenty-Five），启用前使用实时预览；② 下载一个商业/第三方主题 ZIP，通过上传方式安装；③ 用 SFTP/命令行把 <code>wp-academy</code> 示例主题目录复制到 <code>wp-content/themes/</code> 并后台启用。记录每种方式的耗时与体验差异。</p><p><strong>练-12-02（操作题）｜制造并修复「缺少 style.css」</strong></p><p>故意把 <code>wp-academy</code> 主题文件夹再包一层目录压缩成 ZIP，尝试后台上传，观察报错信息。然后按 12.6.1 的排查表修正压缩包结构，重新上传成功。截图报错页与修复后的成功提示。</p><p><strong>练-12-03（操作题）｜主题切换与配置迁移</strong></p><p>当前站点已有菜单、logo、自定义颜色。切换到另一个主题（经典主题或区块主题均可），观察：① 菜单是否还在原位置？② logo 和颜色是否保留？③ 小工具/边栏内容去哪了？按 12.6.5 的方法把配置在新主题下重新配齐，记录需要手动恢复的项。</p><p><strong>练-12-04（故障题）｜模拟白屏回滚</strong></p><p>在 <code>wp-academy</code> 的 <code>functions.php</code> 末尾加一行故意的 PHP 语法错误（如 <code>echo &#39;test</code> 漏引号），保存后刷新前台观察白屏。然后通过 FTP/SFTP 把 <code>wp-academy</code> 目录重命名，观察前台是否恢复。恢复后删除错误代码、改回目录名、重新启用主题。记录完整回滚步骤。</p><p><strong>练-12-05（思考题）｜更新策略设计</strong></p><p>你管理 5 个 WordPress 站点，主题分别是：A 官方库免费主题（无子主题）、B 商业主题（年费订阅）、C 使用子主题定制、D 区块主题（官方默认）、E 自定义开发的内部主题。请为每个站点写出「是否开启自动更新」的决策及理由，并设计一份「主题更新 SOP」检查单（不少于 8 项）。</p>`,144)])])}const P=a(d,[["render",h]]);export{u as __pageData,P as default};
